sp_widget.client_script:
api.controller = function($scope, $window) {
  var c = this;
  c.tab = 'assets';

  c.assetItem = '304edd6697e3c71009e9b62de053afb8';

  // Opens the portal's standard "new incident" form (no sys_id needed)
  c.incidentUrl = '?id=form&table=incident&sys_id=-1';

  c.services = [
    {icon:'💻', title:'Request New Asset', desc:'Laptop, monitor & more', url:'?id=sc_cat_item&sys_id=' + c.assetItem},
    {icon:'🛠️', title:'Report Incident', desc:'Something is broken', url:c.incidentUrl},
    {icon:'📚', title:'Knowledge Base', desc:'Guides & FAQs', url:'?id=kb_home'},
    {icon:'🛒', title:'Service Catalog', desc:'Browse all services', url:'?id=sc_home'}
  ];

  c.go = function(url) { $window.location.href = url; };

  c.greeting = function() {
    var h = new Date().getHours();
    return h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
  };

  c.badge = function(v) {
    v = (v || '').toLowerCase();
    if (/approved|fulfilled|resolved|closed complete/.test(v)) return 'ok';
    if (/pending|new|in progress|requested|on hold/.test(v)) return 'wait';
    if (/reject|cancel/.test(v)) return 'bad';
    return '';
  };
};

sp_widget.css:
.itp{display:grid;grid-template-columns:220px 1fr 300px;gap:20px;background:#f3f5f9;padding:0;font-family:"Segoe UI",Arial,sans-serif;color:#1f2a44;min-height:100vh}
.itp .sidebar{background:#0f1b3d;color:#c9d2ec;padding:20px 0}
.itp .logo{font-size:22px;font-weight:800;color:#fff;padding:0 20px 20px;line-height:1.2}
.itp .logo span{color:#3ddc97}
.itp .nav-item,.itp .nav-sub{display:block;cursor:pointer;color:#c9d2ec;text-decoration:none}
.itp .nav-item{padding:10px 20px;margin:4px 10px;border-radius:8px}
.itp .nav-item.active{background:#3a5bd9;color:#fff}
.itp .nav-group{padding:14px 20px 4px;font-weight:600;color:#fff;font-size:14px}
.itp .nav-sub{padding:6px 20px 6px 34px;font-size:13px}
.itp .nav-sub:hover,.itp .nav-item:hover{color:#fff}
.itp .main{padding:20px 0}

.itp .hero{background:linear-gradient(135deg,#e3e6ff,#d9e4fb);border-radius:14px;padding:28px;margin-bottom:16px}
.itp .hero h2{margin:0 0 6px;font-weight:700}
.itp .hero-search input{width:70%;padding:12px 14px;border:1px solid #cfd6ea;border-radius:8px;margin-top:10px}
.itp .card{background:#fff;border-radius:12px;padding:16px 18px;margin-bottom:16px;box-shadow:0 1px 4px rgba(20,30,60,.08)}
.itp .card-head{display:flex;justify-content:space-between;align-items:center}
.itp .card-head h4,.itp .card h4{margin:0 0 10px;font-weight:700}
.itp .card-head a{color:#3a5bd9;font-size:13px;cursor:pointer}
.itp .svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.itp .svc{border:1px solid #e6eaf3;border-radius:10px;padding:12px;display:flex;gap:10px;align-items:center;cursor:pointer}
.itp .svc:hover{background:#f5f7ff;border-color:#3a5bd9}
.itp .svc-icon{font-size:24px;background:#eef1ff;border-radius:8px;width:42px;height:42px;display:flex;align-items:center;justify-content:center}
.itp .svc small{color:#6b7794}
.itp .tabs{border-bottom:1px solid #e6eaf3;margin-bottom:8px}
.itp .tabs a{display:inline-block;padding:8px 14px;cursor:pointer;color:#6b7794;text-decoration:none}
.itp .tabs a.active{color:#3a5bd9;border-bottom:2px solid #3a5bd9;font-weight:600}
.itp table{width:100%;font-size:13px;border-collapse:collapse}
.itp th{color:#6b7794;font-weight:600;text-align:left;padding:8px}
.itp td{padding:10px 8px;border-top:1px solid #eef1f7}
.itp .empty{text-align:center;color:#8a94ad;padding:14px}
.itp .badge{padding:3px 10px;border-radius:6px;font-size:12px;background:#e9ecf3;color:#444}
.itp .badge.ok{background:#d9f5e5;color:#157347}
.itp .badge.wait{background:#fff0d6;color:#b26a00}
.itp .badge.bad{background:#fde0e0;color:#b02a37}
.itp .right{padding:20px 20px 20px 0}
.itp .task{padding:8px 0;border-bottom:1px dashed #e6eaf3;font-size:13px}
.itp .task small{color:#6b7794}
.itp button{padding:8px 14px;border-radius:8px;cursor:pointer;margin-right:6px;font-size:13px}
.itp .btn-outline{background:#fff;border:1px solid #3a5bd9;color:#3a5bd9}
.itp .btn-solid{background:#3a5bd9;border:1px solid #3a5bd9;color:#fff}
@media(max-width:1100px){.itp{grid-template-columns:1fr}.itp .svc-grid{grid-template-columns:repeat(2,1fr)}.itp .sidebar{display:none}.itp .right{padding:0 16px}}

sp_widget.script:
(function() {
  var userId = gs.getUserID();

  // User name
  var u = new GlideRecord('sys_user');
  u.get(userId);
  data.name = u.first_name.toString() || 'there';

  // Asset requests
  data.assetRequests = [];
  var a = new GlideRecord('x_2238299_itasse_0_asset_request');
  a.addQuery('u_requester', userId);
  a.orderByDesc('sys_created_on');
  a.setLimit(10);
  a.query();
  while (a.next()) {
    data.assetRequests.push({
      item: a.u_requested_item.toString(),
      priority: a.u_priority.getDisplayValue(),
      approval: a.u_approval_status.getDisplayValue(),
      state: a.u_state.getDisplayValue(),
      date: a.sys_created_on.getDisplayValue()
    });
  }

  // Incidents
  data.incidents = [];
  var i = new GlideRecord('incident');
  i.addQuery('caller_id', userId);
  i.orderByDesc('sys_created_on');
  i.setLimit(10);
  i.query();
  while (i.next()) {
    data.incidents.push({
      number: i.number.toString(),
      desc: i.short_description.toString(),
      state: i.state.getDisplayValue(),
      date: i.sys_created_on.getDisplayValue()
    });
  }

  // Approvals waiting for me
  data.approvals = [];
  var p = new GlideRecord('sysapproval_approver');
  p.addQuery('approver', userId);
  p.addQuery('state', 'requested');
  p.query();
  while (p.next()) {
    data.approvals.push({
      what: p.document_id.getDisplayValue(),
      date: p.sys_created_on.getDisplayValue()
    });
  }

  // Announcements (latest published knowledge articles)
  data.news = [];
  var k = new GlideRecord('kb_knowledge');
  k.addQuery('workflow_state', 'published');
  k.orderByDesc('sys_created_on');
  k.setLimit(3);
  k.query();
  while (k.next()) {
    data.news.push({
      title: k.short_description.toString(),
      date: k.sys_created_on.getDisplayValue()
    });
  }
})();
